// === Tab: mySketch ===
function setup() {
	createCanvas(windowWidth, windowHeight);
	// background(100);
}

function draw() {
	background(0)
	for(var i=0;i<width;i+=22){
		for(var o=0;o<height;o+=22){
			push()
				translate(i,o)
				stroke(255)
				let len = sin(i/width*PI)*14
				let angle = noise(i/1000,o/1000,frameCount/100)*20
				let m_angle = atan2((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-o,(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-i)
				angle+=m_angle
				line(0,0,len*cos(angle),len*sin(angle))
				// line(0,0,)
			pop()
		}
	}
	for(var cir=0;cir<9;cir++){
		let baseR = noise(cir+10+frameCount/50)*120
		for(var sp=0;sp<8;sp+=1){
			let useR = baseR*(1+sp/(10+noise(frameCount/5,sp/10)) )
			push()
				translate(100+cir*120+sp*10+noise(frameCount/5,cir+sp/5)*10,height/2)
				stroke(255)
				strokeWeight(1.5)
				noFill()
				beginShape()
				for(var ang=PI/6;ang<2*PI-PI/6;ang+=(Math.max(0.001, Math.abs(PI/140)) || 1)){
					let finalR = useR+map(sp,0,11,100,0)
					if (cir==2){
						let subAng = ang+frameCount/20
						let wSpan = 0.5
						let i_ang = floor(subAng/wSpan)
						let f_ang = subAng/wSpan-i_ang
						let r_md = (map(f_ang,0,wSpan/2,0,1,true)+map(f_ang,wSpan/2,wSpan,1,0,true))/2
						finalR+=r_md*20
					}
					if (cir==3 ){
						finalR+=noise(ang*50,frameCount/8,sp)*80-40
					}
					if (cir==4){
						finalR+=noise(ang*50,frameCount/5,sp)*200-100
					}
					if (cir==5){
						finalR+=noise(ang*50,frameCount/8,sp)*20-10
					}
					if (cir==7){
						finalR+=sin(ang*20+frameCount/(5+sp/5)+sp,sp)*5
					}
					vertex(finalR*cos(ang)/2,finalR*sin(ang))	
				}
				if (cir==1){
					strokeWeight(2)
				}
				endShape()
				// arc(0,0,useR/2,useR,PI/5,-PI/5)
			pop()
		}
	}
	ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 20, 20);
}

